// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.Resources;

/**
 * Adjacency must come back after every degradation: a store that keeps answering from LMDB forever also keeps queueing
 * commit deltas that nothing drains.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
@Timeout(value = 2, unit = TimeUnit.MINUTES)
class LmdbDirectAdjacencyRecoveryTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final IRI P = F.createIRI("http://example.org/recovery/p");

	@TempDir
	File dataDir;

	private String previousCommitMaxBytes;
	private SailRepository repo;

	@AfterEach
	void tearDown() {
		try {
			if (repo != null) {
				repo.shutDown();
			}
		} finally {
			if (previousCommitMaxBytes == null) {
				System.clearProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY);
			} else {
				System.setProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY, previousCommitMaxBytes);
			}
		}
	}

	@Test
	void aGapRecordedWhileARebuildWaitsForAViewStillRebuildsOnceTheViewCloses() throws Exception {
		previousCommitMaxBytes = System.getProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY);
		// A commit delta larger than this overflows its collector, which records a gap.
		System.setProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY, "4096");
		LmdbStore sail = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		repo = new SailRepository(sail);
		repo.init();
		Set<Statement> expected = new HashSet<>();
		try (RepositoryConnection connection = repo.getConnection()) {
			for (int i = 0; i < 5; i++) {
				Statement statement = F.createStatement(F.createIRI("http://example.org/recovery/s0"), P,
						F.createIRI("http://example.org/recovery/o" + i));
				connection.add(statement);
				expected.add(statement);
			}
		}
		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
		LmdbSailStore backing = sail.getBackingStore();
		LmdbDirectAdjacencyStore direct = backing.directAdjacencyStore();

		try (LmdbAdjacencyReadView view = direct.acquire(backing.getTripleStore().getDataRevision())) {
			assertThat(view.servesSnapshot()).as("an exact view holds the published index").isTrue();
			direct.scheduleQuiescentRebuild();
			awaitState(sail, "QUIESCING_FOR_REBUILD");
			try (RepositoryConnection connection = repo.getConnection()) {
				connection.begin();
				for (int i = 0; i < 500; i++) {
					Statement statement = F.createStatement(F.createIRI("http://example.org/recovery/s" + i), P,
							F.createIRI("http://example.org/recovery/bulk"));
					connection.add(statement);
					expected.add(statement);
				}
				connection.commit();
			}
			awaitState(sail, "DEGRADED_GAP");
		}

		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS))
				.as("the waiting rebuild resumes when the view closes: %s",
						sail.getDirectAdjacencyReadinessDescription())
				.isTrue();
		long hitsBefore = direct.snapshotMetrics().lookupHits;
		try (RepositoryConnection connection = repo.getConnection()) {
			Set<Statement> actual = new HashSet<>();
			try (RepositoryResult<Statement> result = connection.getStatements(null, P,
					F.createIRI("http://example.org/recovery/bulk"), false)) {
				result.forEach(actual::add);
			}
			try (RepositoryResult<Statement> result = connection.getStatements(
					F.createIRI("http://example.org/recovery/s0"), P, null, false)) {
				result.forEach(actual::add);
			}
			assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		}
		assertThat(direct.snapshotMetrics().lookupHits).as("adjacency serves again").isGreaterThan(hitsBefore);
	}

	private static void awaitState(LmdbStore sail, String state) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (!sail.getDirectAdjacencyReadinessDescription().startsWith("state=" + state)) {
			assertThat(System.nanoTime() - deadline).as("reached %s: %s", state,
					sail.getDirectAdjacencyReadinessDescription()).isNegative();
			Thread.sleep(5);
		}
	}
}
